// One policy per resource class, not one number for the whole app
enum class Freshness(val ttl: Duration) {
  NEAR_STATIC(24.hours),   // render stale, revalidate in the background
  USER_OWNED(5.minutes),   // stale-while-revalidate
  VOLATILE(Duration.ZERO)  // never render silently from cache
}

@Entity
data class CachedResource(
  @PrimaryKey val key: String,   // scope by user + locale, or accounts leak into each other
  val etag: String?,             // the validator lives next to what it validates
  val fetchedAt: Long,
  val body: String
)

suspend fun load(key: String, freshness: Freshness): CachedResource {
  val row = dao.find(key)
  if (row != null && now() - row.fetchedAt < freshness.ttl.inWholeMilliseconds) return row

  val response = api.get(key, ifNoneMatch = row?.etag)
  return if (response.code == 304) {
    dao.touch(key, now())                                         // headers, no payload
    row!!.copy(fetchedAt = now())
  } else {
    CachedResource(key, response.etag, now(), response.body).also { dao.upsert(it) }
  }
}

