@Entity(tableName = "upload_queue")
data class UploadJob(
  @PrimaryKey val id: String = UUID.randomUUID().toString(),   // also the idempotency key
  val localPath: String,          // our own copy: the picker's content:// grant will be gone
  val postId: String,
  val uploadUrl: String? = null,  // resumable session, so a retry continues from its offset
  val bytesSent: Long = 0,
  val attempts: Int = 0
)

suspend fun enqueuePhoto(source: Uri, caption: String) = db.withTransaction {
  val copy = files.copyIntoAppStorage(source)                  // step 1, before anything async
  val post = posts.insertPending(caption)                      // optimistic, visible now
  queue.insert(UploadJob(localPath = copy.path, postId = post.id))

  workManager.enqueueUniqueWork(
    "upload-${post.id}",
    ExistingWorkPolicy.KEEP,
    OneTimeWorkRequestBuilder<UploadWorker>()
      .setConstraints(Constraints(requiredNetworkType = NetworkType.CONNECTED))
      .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
      .build()
  )
}

// In the worker: resume, and give up on errors that will never succeed
suspend fun upload(job: UploadJob): Result = when (val r = uploader.resume(job)) {
  is Done -> { posts.attachAsset(job.postId, r.assetId); queue.delete(job.id); Result.success() }
  is Retryable -> if (job.attempts < 10) Result.retry() else fail(job)
  is Permanent -> fail(job)          // 413 / 415: tell the user, stop burning battery
}

