// Right: one offset, refreshed on every response, applied wherever "now" is needed
class ServerTime {
  @Volatile private var offsetMillis = 0L

  fun sync(serverEpochMillis: Long) {
    offsetMillis = serverEpochMillis - System.currentTimeMillis()
  }

  fun now(): Long = System.currentTimeMillis() + offsetMillis
}

class TimeInterceptor(private val time: ServerTime) : Interceptor {
  override fun intercept(chain: Interceptor.Chain): Response =
    chain.proceed(chain.request()).also { response ->
      response.headers.getDate("Date")?.let { time.sync(it.time) }
    }
}

// Display uses server-anchored time; eligibility is still the server's answer
val remaining = offer.endsAtMillis - serverTime.now()

// Durations inside a session use the monotonic clock, which cannot jump
val startedAt = SystemClock.elapsedRealtime()
val elapsed = SystemClock.elapsedRealtime() - startedAt

// Persisted TTL has to use wall time, so defend against a clock that was wrong
fun isFresh(row: CachedRow, ttl: Long): Boolean {
  val age = serverTime.now() - row.fetchedAt
  return age in 0..ttl            // a negative age means a bad clock: treat it as stale
}

