// Right: an opaque server cursor, tombstones, and one transaction for rows + cursor
@Serializable
data class ChangePage(
  val changes: List<Change>,                   // Change.Upsert or Change.Delete
  val nextCursor: String,
  val hasMore: Boolean
)

suspend fun sync() {
  var cursor = cursors.get("feed")             // null on a first run or after a reset
  do {
    val page = try {
      api.changes(cursor)
    } catch (e: HttpException) {
      if (e.code() == 410) { fullResync(); return } else throw e  // token too old, not a retry
    }

    db.withTransaction {                       // rows and cursor advance together, or neither does
      page.changes.forEach { c ->
        when (c) {
          is Change.Upsert -> dao.upsert(c.entity)
          is Change.Delete -> dao.delete(c.id)  // tombstone: a missing row is not a signal
        }
      }
      cursors.put("feed", page.nextCursor)
    }
    cursor = page.nextCursor
  } while (page.hasMore)

  status.recordSuccess(serverTime.now())       // surfaced in the UI and in telemetry
}
